import{_ as l,I as a,o as r,c as d,b6 as s,J as i}from"./chunks/framework.COUcLbTA.js";const u=JSON.parse('{"title":"测试策略","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/9-engineering-excellence/testing-strategies.md","filePath":"zh-cn/appendix/9-engineering-excellence/testing-strategies.md"}'),h={name:"zh-cn/appendix/9-engineering-excellence/testing-strategies.md"};function o(p,t,g,c,k,b){const n=a("TestPyramidDemo"),e=a("TDDCycleDemo");return r(),d("div",null,[t[0]||(t[0]=s('<h1 id="测试策略" tabindex="-1">测试策略 <a class="header-anchor" href="#测试策略" aria-label="Permalink to “测试策略”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">前言</p><p><strong>你的代码真的&quot;没问题&quot;吗？</strong> 每次改完代码手动点一遍看看有没有坏——这种方式在项目小的时候还能凑合，但当代码量增长到几万行、团队扩展到十几人时，&quot;手动点点看&quot;就是一场灾难。</p><p>本章带你理解软件测试的核心策略，从测试金字塔到 TDD，建立系统化的质量保障思维。</p></div><p><strong>这篇文章会带你学什么？</strong></p><table tabindex="0"><thead><tr><th>章节</th><th>内容</th><th>核心概念</th></tr></thead><tbody><tr><td><strong>第 1 章</strong></td><td>测试金字塔</td><td>测试的层次与比例</td></tr><tr><td><strong>第 2 章</strong></td><td>单元测试实战</td><td>如何写好一个测试</td></tr><tr><td><strong>第 3 章</strong></td><td>TDD 驱动开发</td><td>红绿重构循环</td></tr><tr><td><strong>第 4 章</strong></td><td>测试策略选择</td><td>不同场景的方案</td></tr></tbody></table><p>学完本章，你将理解如何为项目选择合适的测试策略，写出有价值的测试，并通过 TDD 提升代码设计质量。</p><hr><h2 id="_0-全景图-为什么需要自动化测试" tabindex="-1">0. 全景图：为什么需要自动化测试？ <a class="header-anchor" href="#_0-全景图-为什么需要自动化测试" aria-label="Permalink to “0. 全景图：为什么需要自动化测试？”">​</a></h2><p>想象你是一个建筑工程师。每次修改图纸后，你不会亲自爬上每一层楼去检查结构是否安全——你会依赖一套<strong>自动化的检测系统</strong>。软件测试就是代码世界的&quot;结构检测系统&quot;。</p><div class="tip custom-block"><p class="custom-block-title">自动化测试的价值</p><ul><li><strong>回归保护</strong>：修改 A 功能时，自动检测 B、C、D 功能是否被影响</li><li><strong>重构信心</strong>：有测试覆盖的代码，重构时心里有底</li><li><strong>活文档</strong>：好的测试就是最好的使用说明书</li><li><strong>快速反馈</strong>：几秒钟内知道代码是否正确，而不是等到部署后才发现问题</li></ul></div><hr><h2 id="_1-测试金字塔-测试的层次与比例" tabindex="-1">1. 测试金字塔：测试的层次与比例 <a class="header-anchor" href="#_1-测试金字塔-测试的层次与比例" aria-label="Permalink to “1. 测试金字塔：测试的层次与比例”">​</a></h2><h3 id="_1-1-三层金字塔" tabindex="-1">1.1 三层金字塔 <a class="header-anchor" href="#_1-1-三层金字塔" aria-label="Permalink to “1.1 三层金字塔”">​</a></h3><p>Mike Cohn 提出的测试金字塔是测试策略的经典模型。它告诉我们：<strong>不同类型的测试应该有不同的数量比例</strong>。</p><p>通过下面的交互组件，点击金字塔的每一层，了解各层测试的特点：</p>',14)),i(n),t[1]||(t[1]=s(`<h3 id="_1-2-为什么是金字塔形" tabindex="-1">1.2 为什么是金字塔形？ <a class="header-anchor" href="#_1-2-为什么是金字塔形" aria-label="Permalink to “1.2 为什么是金字塔形？”">​</a></h3><p>金字塔形状反映了一个核心权衡：<strong>速度与真实度的取舍</strong>。</p><ul><li><strong>底层（单元测试）</strong>：速度极快、数量最多、成本最低，但只能验证单个零件</li><li><strong>中层（集成测试）</strong>：速度适中、数量适中，验证零件之间的配合</li><li><strong>顶层（E2E 测试）</strong>：最接近真实用户，但速度慢、维护成本高、容易因环境问题失败</li></ul><blockquote><p><strong>反模式：冰淇淋甜筒</strong> —— 如果你的项目 E2E 测试最多、单元测试最少，那就是倒过来的&quot;冰淇淋甜筒&quot;。这意味着测试套件运行缓慢、经常失败、维护成本极高。</p></blockquote><hr><h2 id="_2-单元测试实战" tabindex="-1">2. 单元测试实战 <a class="header-anchor" href="#_2-单元测试实战" aria-label="Permalink to “2. 单元测试实战”">​</a></h2><h3 id="_2-1-什么是好的单元测试" tabindex="-1">2.1 什么是好的单元测试？ <a class="header-anchor" href="#_2-1-什么是好的单元测试" aria-label="Permalink to “2.1 什么是好的单元测试？”">​</a></h3><p>好的单元测试遵循 <strong>FIRST</strong> 原则：</p><table tabindex="0"><thead><tr><th>原则</th><th>含义</th><th>说明</th></tr></thead><tbody><tr><td><strong>F</strong>ast</td><td>快速</td><td>毫秒级完成，开发者愿意频繁运行</td></tr><tr><td><strong>I</strong>ndependent</td><td>独立</td><td>测试之间互不依赖，可以单独运行</td></tr><tr><td><strong>R</strong>epeatable</td><td>可重复</td><td>任何环境下运行结果一致</td></tr><tr><td><strong>S</strong>elf-validating</td><td>自验证</td><td>结果是明确的通过/失败，不需要人工判断</td></tr><tr><td><strong>T</strong>imely</td><td>及时</td><td>在写代码的同时（或之前）写测试</td></tr></tbody></table><h3 id="_2-2-测试的结构-aaa-模式" tabindex="-1">2.2 测试的结构：AAA 模式 <a class="header-anchor" href="#_2-2-测试的结构-aaa-模式" aria-label="Permalink to “2.2 测试的结构：AAA 模式”">​</a></h3><p>每个测试都应该有清晰的三段式结构：</p><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;应该正确计算含税价格&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Arrange（准备）—— 设置测试数据</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> price</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> taxRate</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.13</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Act（执行）—— 调用被测函数</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> calculateTotalWithTax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(price, taxRate)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Assert（断言）—— 验证结果</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  expect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toBe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">113</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><h3 id="_2-3-测试什么-不测什么" tabindex="-1">2.3 测试什么？不测什么？ <a class="header-anchor" href="#_2-3-测试什么-不测什么" aria-label="Permalink to “2.3 测试什么？不测什么？”">​</a></h3><p><strong>应该测试的：</strong></p><ul><li>核心业务逻辑（价格计算、权限判断、数据转换）</li><li>边界条件（空值、零、负数、超大数）</li><li>错误处理路径</li></ul><p><strong>不需要测试的：</strong></p><ul><li>第三方库的内部实现</li><li>简单的 getter/setter</li><li>框架自身的功能（如 Vue 的响应式系统）</li></ul><hr><h2 id="_3-tdd-测试驱动开发" tabindex="-1">3. TDD：测试驱动开发 <a class="header-anchor" href="#_3-tdd-测试驱动开发" aria-label="Permalink to “3. TDD：测试驱动开发”">​</a></h2><h3 id="_3-1-红绿重构循环" tabindex="-1">3.1 红绿重构循环 <a class="header-anchor" href="#_3-1-红绿重构循环" aria-label="Permalink to “3.1 红绿重构循环”">​</a></h3><p>TDD（Test-Driven Development）的核心是一个简单的循环：<strong>先写测试，再写实现，最后重构</strong>。</p><p>通过下面的交互组件，亲自体验 TDD 的完整循环：</p>`,22)),i(e),t[2]||(t[2]=s(`<h3 id="_3-2-tdd-的三条规则" tabindex="-1">3.2 TDD 的三条规则 <a class="header-anchor" href="#_3-2-tdd-的三条规则" aria-label="Permalink to “3.2 TDD 的三条规则”">​</a></h3><ol><li><strong>不写任何产品代码，除非是为了让一个失败的测试通过</strong></li><li><strong>只写刚好让测试失败的测试代码</strong>（编译不过也算失败）</li><li><strong>只写刚好让测试通过的产品代码</strong></li></ol><h3 id="_3-3-tdd-的真正价值" tabindex="-1">3.3 TDD 的真正价值 <a class="header-anchor" href="#_3-3-tdd-的真正价值" aria-label="Permalink to “3.3 TDD 的真正价值”">​</a></h3><p>TDD 的价值不仅在于&quot;先写测试&quot;，更在于它<strong>迫使你思考接口设计</strong>。当你先写测试时，你是站在&quot;使用者&quot;的角度思考：这个函数应该接收什么参数？返回什么结果？这自然会导向更好的 API 设计。</p><div class="tip custom-block"><p class="custom-block-title">TDD 不是银弹</p><p>TDD 适合逻辑密集的代码（算法、业务规则、数据转换），但对于 UI 布局、探索性原型等场景，强制 TDD 反而会拖慢速度。关键是理解它的思想，灵活运用。</p></div><hr><h2 id="_4-测试策略选择" tabindex="-1">4. 测试策略选择 <a class="header-anchor" href="#_4-测试策略选择" aria-label="Permalink to “4. 测试策略选择”">​</a></h2><h3 id="_4-1-不同项目的测试重点" tabindex="-1">4.1 不同项目的测试重点 <a class="header-anchor" href="#_4-1-不同项目的测试重点" aria-label="Permalink to “4.1 不同项目的测试重点”">​</a></h3><table tabindex="0"><thead><tr><th>项目类型</th><th>测试重点</th><th>推荐比例</th></tr></thead><tbody><tr><td><strong>工具库/SDK</strong></td><td>单元测试为主</td><td>90% 单元 + 10% 集成</td></tr><tr><td><strong>API 服务</strong></td><td>集成测试为主</td><td>30% 单元 + 60% 集成 + 10% E2E</td></tr><tr><td><strong>Web 应用</strong></td><td>均衡分布</td><td>50% 单元 + 30% 集成 + 20% E2E</td></tr><tr><td><strong>MVP/原型</strong></td><td>关键路径 E2E</td><td>少量核心测试即可</td></tr></tbody></table><h3 id="_4-2-常用测试工具" tabindex="-1">4.2 常用测试工具 <a class="header-anchor" href="#_4-2-常用测试工具" aria-label="Permalink to “4.2 常用测试工具”">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>类型</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>Vitest</strong></td><td>单元/集成</td><td>Vite 项目首选，兼容 Jest API</td></tr><tr><td><strong>Jest</strong></td><td>单元/集成</td><td>Node.js 生态最流行</td></tr><tr><td><strong>Playwright</strong></td><td>E2E</td><td>跨浏览器，微软出品</td></tr><tr><td><strong>Cypress</strong></td><td>E2E</td><td>开发体验好，调试方便</td></tr><tr><td><strong>Testing Library</strong></td><td>组件测试</td><td>以用户视角测试 UI 组件</td></tr></tbody></table><hr><h2 id="_5-ai-助力-用大模型提升测试效率" tabindex="-1">5. AI 助力：用大模型提升测试效率 <a class="header-anchor" href="#_5-ai-助力-用大模型提升测试效率" aria-label="Permalink to “5. AI 助力：用大模型提升测试效率”">​</a></h2><p>大模型在测试领域的能力已经非常强大——它可以帮你生成测试用例、发现边界条件、甚至写出完整的测试代码。</p><h3 id="_5-1-生成单元测试" tabindex="-1">5.1 生成单元测试 <a class="header-anchor" href="#_5-1-生成单元测试" aria-label="Permalink to “5.1 生成单元测试”">​</a></h3><blockquote><p><strong>提示词</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请为以下函数编写单元测试，使用 Vitest 框架，要求：</span></span>
<span class="line"><span>1. 遵循 AAA 模式（Arrange-Act-Assert）</span></span>
<span class="line"><span>2. 覆盖正常路径、边界条件和错误路径</span></span>
<span class="line"><span>3. 每个测试用例有清晰的中文描述</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴你的函数代码]</span></span></code></pre></div></blockquote><h3 id="_5-2-发现边界条件" tabindex="-1">5.2 发现边界条件 <a class="header-anchor" href="#_5-2-发现边界条件" aria-label="Permalink to “5.2 发现边界条件”">​</a></h3><blockquote><p><strong>提示词</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>分析以下函数，列出所有可能的边界条件和极端输入场景，</span></span>
<span class="line"><span>包括：空值、零、负数、超大数、特殊字符、并发情况等。</span></span>
<span class="line"><span>对每个场景说明预期行为和可能的风险。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴你的函数代码]</span></span></code></pre></div></blockquote><h3 id="_5-3-从需求生成测试-tdd-辅助" tabindex="-1">5.3 从需求生成测试（TDD 辅助） <a class="header-anchor" href="#_5-3-从需求生成测试-tdd-辅助" aria-label="Permalink to “5.3 从需求生成测试（TDD 辅助）”">​</a></h3><blockquote><p><strong>提示词</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我要实现一个购物车模块，需求如下：</span></span>
<span class="line"><span>- 添加商品、删除商品、修改数量</span></span>
<span class="line"><span>- 自动计算总价（含折扣）</span></span>
<span class="line"><span>- 库存不足时提示错误</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按照 TDD 思路，先写出测试用例（不写实现），</span></span>
<span class="line"><span>使用 Vitest，覆盖所有核心场景。</span></span></code></pre></div></blockquote><div class="tip custom-block"><p class="custom-block-title">AI 使用建议</p><p>AI 生成的测试要检查断言是否有意义——避免 <code>expect(true).toBe(true)</code> 这种无效测试。好的测试应该在代码出错时真的能失败。</p></div><hr><h2 id="_6-总结" tabindex="-1">6. 总结 <a class="header-anchor" href="#_6-总结" aria-label="Permalink to “6. 总结”">​</a></h2><ol><li><strong>测试金字塔</strong>：底层多、顶层少，平衡速度与真实度</li><li><strong>单元测试</strong>：遵循 FIRST 原则和 AAA 模式，测试核心逻辑</li><li><strong>TDD</strong>：红绿重构循环，用测试驱动设计</li><li><strong>策略选择</strong>：根据项目类型和阶段，选择合适的测试比例</li></ol><div class="tip custom-block"><p class="custom-block-title">终极思考</p><p>测试不是负担，而是<strong>加速器</strong>。短期看，写测试确实多花了时间；长期看，它节省了无数次手动验证、排查回归 Bug、以及深夜紧急修复的时间。好的测试让你有信心说出那句话：<strong>&quot;放心改，测试会告诉我们有没有问题。&quot;</strong></p></div><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2><ul><li><strong>经典书籍</strong>：Kent Beck《测试驱动开发》是 TDD 的开山之作。</li><li><strong>实用指南</strong>：尝试用 Vitest 为一个小项目写测试，体验从零开始的测试流程。</li><li><strong>测试模式</strong>：了解 Mock、Stub、Spy 的区别和使用场景。</li><li><strong>持续集成</strong>：将测试集成到 CI/CD 流水线中，每次提交自动运行。</li></ul>`,28))])}const D=l(h,[["render",o]]);export{u as __pageData,D as default};
